from functools import cache

class Solution:
    def minimumCost(self, sentence: str, k: int) -> int:
        words = sentence.split()
        n = len(words)

        @cache
        def dp(i):
            if i == n:
                return 0
            best = float('inf')
            length = 0
            for j in range(i, n):
                length += len(words[j])
                if j > i:
                    length += 1
                if length > k:
                    break
                cost = 0 if j + 1 == n else (k - length) ** 2 + dp(j + 1)
                best = min(best, cost)
            return best

        return dp(0)

