class Solution {
public:
    int minimumCost(string sentence, int k) {
        vector<string> words;
        stringstream ss(sentence);
        string w;
        while (ss >> w) words.push_back(w);
        int n = words.size();
        vector<long long> memo(n + 1, -1);
        function<long long(int)> dp = [&](int i) -> long long {
            if (i == n) return 0;
            long long& res = memo[i];
            if (res != -1) return res;
            long long best = LLONG_MAX;
            long long length = -(long long)words[i].size();
            for (int j = i; j < n; ++j) {
                length += (long long)words[j].size() + 1;
                if (length > k) break;
                long long cost = dp(j + 1);
                if (j + 1 != n) cost += (long long)(k - length) * (k - length);
                best = min(best, cost);
            }
            return res = best;
        };
        return (int)dp(0);
    }
};

