class Solution {
    private String[] words;
    private int k, n;
    private long[] memo;

    public int minimumCost(String sentence, int k) {
        words = sentence.split(" ");
        n = words.length;
        this.k = k;
        memo = new long[n + 1];
        Arrays.fill(memo, -1L);
        return (int) dp(0);
    }

    private long dp(int i) {
        if (i == n) return 0;
        if (memo[i] != -1) return memo[i];
        long best = Long.MAX_VALUE;
        int length = -words[i].length();
        for (int j = i; j < n; j++) {
            length += words[j].length() + 1;
            if (length > k) break;
            long cost = dp(j + 1);
            if (j + 1 != n) cost += (long)(k - length) * (k - length);
            best = Math.min(best, cost);
        }
        return memo[i] = best;
    }
}

