        n = len(words)
        pref = [0]
        for w in words:
            pref.append(pref[-1] + len(w))
        INF = float('inf')
        dp = [INF] * (n + 1)
        dp[0] = 0
        for i in range(1, n + 1):
            j = i - 1
            while j >= 0:
                length = pref[i] - pref[j] + (i - 1 - j)
                if length > k:
                    break
                if dp[j] != INF:
                    dp[i] = min(dp[i], dp[j] + (k - length) ** 2)
                j -= 1
        best = INF
        for j in range(n):
            length = pref[n] - pref[j] + (n - 1 - j)
            if length <= k:
                best = min(best, dp[j])
        return best

