class Solution {
public:
    int minimumCost(string sentence, int k) {
        vector<string> words;
        stringstream ss(sentence);
        string w;
        while (ss >> w) words.push_back(w);
        int n = words.size();
        vector<long long> pref(n + 1, 0);
        for (int i = 0; i < n; ++i) pref[i + 1] = pref[i] + words[i].size();
        const long long INF = LLONG_MAX / 4;
        vector<long long> dp(n + 1, INF);
        dp[0] = 0;
        for (int i = 1; i <= n; ++i)
            for (int j = i - 1; j >= 0; --j) {
                long long length = pref[i] - pref[j] + (i - 1 - j);
                if (length > k) break;
                if (dp[j] < INF)
                    dp[i] = min(dp[i], dp[j] + (k - length) * (k - length));
            }
        long long best = INF;
        for (int j = 0; j < n; ++j) {
            long long length = pref[n] - pref[j] + (n - 1 - j);
            if (length <= k) best = min(best, dp[j]);
        }
        return (int)best;
    }
};

